// src/components/About.tsx
const About = () => {
  return (
    <section id="about" className="py-20 px-6 bg-gray-800">
      <div className="max-w-4xl mx-auto">
        <h3 className="text-3xl font-semibold mb-6">About Me</h3>
        <p className="text-gray-300 leading-relaxed">
          I'm a recent CS graduate who loves solving problems and building useful applications.
          Currently focused on learning full-stack development and deploying real-world projects.
        </p>
      </div>
    </section>
  );
};

export default About;
